from math import lcm
from typing import List


def kth_smallest_amount(coins: List[int], k: int) -> int:
    """Return the k-th distinct positive multiple of any denomination.

    An amount can use arbitrarily many coins of one denomination, but cannot
    combine different denominations. ``coins`` contains 1 to 15 distinct
    positive integers, each at most 25; ``k`` is one-based and at most 2 * 10**9.
    The input list is not modified.

    >>> kth_smallest_amount([3, 6, 9], 3)
    9
    >>> kth_smallest_amount([5, 2], 7)
    12
    """
    # Multiples of an existing smaller denomination add no new amounts.
    denominations = []
    for coin in sorted(set(coins)):
        if not any(coin % smaller == 0 for smaller in denominations):
            denominations.append(coin)

    low = denominations[0]
    high = low * k  # The smallest denomination alone supplies k amounts.
    if len(denominations) == 1:
        return high

    # Inclusion-exclusion counts the union of the denominations' multiples.
    # Subsets with the same LCM have identical contributions, so combine their
    # signed coefficients. LCMs above high cannot contribute during the search.
    coefficients = {}
    for coin in denominations:
        changes = {coin: 1}
        for divisor, coefficient in coefficients.items():
            common_multiple = lcm(divisor, coin)
            if common_multiple <= high:
                changes[common_multiple] = (
                    changes.get(common_multiple, 0) - coefficient
                )
        for divisor, change in changes.items():
            coefficient = coefficients.get(divisor, 0) + change
            if coefficient:
                coefficients[divisor] = coefficient
            else:
                coefficients.pop(divisor, None)

    terms = tuple(coefficients.items())
    while low < high:
        middle = (low + high) // 2
        count = sum(coefficient * (middle // divisor)
                    for divisor, coefficient in terms)
        if count >= k:
            high = middle
        else:
            low = middle + 1
    return low
